			case "deployment-kind":
				objects["deployment"]["items"].([]any)[0].(map[string]any)["kind"] = "ReplicaSet"
			case "owner-name":
				first["name"] = "foreign"
			case "owner-kind":
				first["kind"] = "StatefulSet"
			case "owner-uid":
